local HOOKS={{0x80045378,{0x26040028,0x9602002A,0x02002821,0x30420FFF},{0x0C036000,0x00000000,0x00000000,0x00000000}},{0x8001F3D8,{0x96020028,0x9603002A},{0x0C036030,0x00000000}},{0x8005B29C,{0x96020020,0x97A30010},{0x0C03605E,0x00000000}},{0x8006B81C,{0x3C068007,0x24C6E17C},{0x0803608E,0x00000000}},{0x80015268,{0x0C0056EF},{0x0C03609A}},{0x8004DA48,{0x27BDFFE0,0x3C02800C},{0x080360C0,0x00000000}},{0x8004DF20,{0x0801383F},{0x080360CF}},{0x8006B074,{0x30420002,0x1040002B},{0x080360A2,0x00000000}},{0x8006C194,{0x30420002,0x10400006},{0x080360B1,0x00000000}},{0x8006E364,{0x04400060},{0x080360DD}},{0x8006D46C,{0x24A5FFFF,0x04A000C8},{0x080360EA,0x00000000}},{0x8006D7C8,{0x24A5FFFF,0x04A00090},{0x080360F6,0x00000000}},{0x8006DAE4,{0x24A5FFFF,0x04A0006D},{0x08036102,0x00000000}},{0x8006DD14,{0x24A5FFFF,0x04A0008A},{0x0803610E,0x00000000}},{0x8006DFB8,{0x24A5FFFF,0x04A00064},{0x0803611A,0x00000000}},{0x8006E2EC,{0x24A5FFFF,0x04A0007F},{0x08036126,0x00000000}},{0x8006E588,{0x24A5FFFF,0x04A0005C},{0x08036132,0x00000000}},{0x8006E79C,{0x24A5FFFF,0x04A00072},{0x0803613E,0x00000000}},{0x8006B5C4,{0x30420003,0x144300BE},{0x30420003,0x144300BE}},{0x8006B174,{0x30420002,0x1040001E},{0x30420002,0x1040001E}},{0x8004395C,{0x27A30010,0x3C028001,0x244206C4,0x24440030,0xAFBF0054,0xAFB3004C,0xAFB20048,0xAFB10044,0xAFB00040,0x8C480000},{0xAFBF0054,0xAFB3004C,0xAFB20048,0xAFB10044,0xAFB00040,0x3C13800D,0x36739EB8,0x00009021,0x08010E6E,0x26710001}},{0x80043A14,{0x2E420006},{0x2E420007}},{0x80043874,{0x2C420004},{0x2C420005}},{0x80043814,{0x3C028009},{0x3C02800E}},{0x80043904,{0x2442535C},{0x24429EA0}}}
local function flush() pcall(function() local s=PCSX.createSaveState() PCSX.loadSaveState(s) end) end
-- dc6.hookOff(0x8004DA48): repone el original de UN enganche (para aislar un
-- problema: instalar, sacar uno, probar). dc6.hookOn(dir) lo vuelve a poner.
function dc6.hookOff(a) for _,h in ipairs(HOOKS) do if h[1]==a then for i,w in ipairs(h[2]) do wr(a+(i-1)*4,w) end flush() print(string.format('[dc6] enganche %08X quitado',a)) return end end print('[dc6] no existe ese enganche') end
function dc6.hookOn(a) for _,h in ipairs(HOOKS) do if h[1]==a then for i,w in ipairs(h[3]) do wr(a+(i-1)*4,w) end flush() print(string.format('[dc6] enganche %08X puesto',a)) return end end print('[dc6] no existe ese enganche') end
-- dc6.cap(true/false): pone/quita el tope duro del buffer de paquetes (8 enganches)
local CAPS={0x8006D46C,0x8006D7C8,0x8006DAE4,0x8006DD14,0x8006DFB8,0x8006E2EC,0x8006E588,0x8006E79C}
function dc6.cap(on) for _,a in ipairs(CAPS) do for _,h in ipairs(HOOKS) do if h[1]==a then for i,w in ipairs(on and h[3] or h[2]) do wr(a+(i-1)*4,w) end end end end flush() print('[dc6] tope del buffer de paquetes: '..(on and 'PUESTO' or 'QUITADO')) end
-- dc6.sort(n): orden de dibujo del escenario con la camara al hombro, en vivo
-- (0 = Z minima, 1 = Z maxima, 2 = prioridad fija del juego, 3 = pivote de la malla)
local SORTT={[0]=0x8006B7D8,[1]=0x8006B7F8,[2]=0x8006B820,[3]=0x8006B840}
function dc6.sort(n) if n and SORTT[n] then wr(0x800DA0A0,SORTT[n]) end local c=rd(0x800DA0A0) for k,v in pairs(SORTT) do if v==c then print('[dc6] orden de dibujo al hombro: modo '..k) end end end
function dc6.install()
  if dct and dct.off then dct.off() end
  for _,h in ipairs(HOOKS) do
    for i,w in ipairs(h[2]) do
      local g=rd(h[1]+(i-1)*4)
      -- vale el original, el nuevo, o un enganche de OTRA version del parche
      -- (jal/j al bloque 0x800D8000..0x800E0000, o el nop que lo acompana)
      local op=bit.band(g,0xFC000000)
      local tgt=bit.band(g,0x03FFFFFF)*4
      local mine=(op==0x0C000000 or op==0x08000000) and tgt>=0x0D8000 and tgt<0x0E0000
      local same=bit.band(g,0xFFFF0000)==bit.band(h[3][i],0xFFFF0000)
      if g~=w and g~=h[3][i] and g~=0 and not mine and not same then
        print(string.format('[dc6] %08X no es lo esperado (%08X): nada instalado',h[1]+(i-1)*4,g)) return
      end
    end
  end
  for i,w in ipairs(BLOB) do wr(dc6.BASE+(i-1)*4,w) end
  for _,h in ipairs(HOOKS) do for i,w in ipairs(h[3]) do wr(h[1]+(i-1)*4,w) end end
  flush()
  local n=0 for _,h in ipairs(HOOKS) do if h[2][1]~=h[3][1] then n=n+1 end end
  print(string.format('[dc6] instalado: %d bytes en 0x%08X, %d enganches',#BLOB*4,dc6.BASE,n))
end
function dc6.remove()
  for _,h in ipairs(HOOKS) do for i,w in ipairs(h[2]) do wr(h[1]+(i-1)*4,w) end end
  flush() print('[dc6] enganches restaurados')
end
function dc6.verify()
  local bad=0
  for i,w in ipairs(BLOB) do if i*4<=0x800D9E60-0x800D8000 and rd(dc6.BASE+(i-1)*4)~=w then bad=bad+1 end end
  print(bad==0 and '[dc6] codigo intacto' or ('[dc6] '..bad..' palabras de codigo pisadas'))
end
function dc6.cut(n)  wr8(0x800DA0C1, n) print('[dc6] cancelar el disparo desde el frame '..n) end
function dc6.pump(n) wr8(0x800DA0C0, n) print('[dc6] cancelar el bombeo desde el frame '..n) end
function dc6.cuts() print(string.format('[dc6] disparo=%d bombeo=%d', rd8(0x800DA0C1), rd8(0x800DA0C0))) end
local function rd16(a) return m8[bit.band(a,0x1FFFFF)] + m8[bit.band(a+1,0x1FFFFF)]*256 end
local function wr16(a,v) wr8(a,v) wr8(a+1,bit.rshift(v,8)) end
-- HUD: posiciones en vivo (pixeles de pantalla; la fuente avanza 8 px por letra).
--   dc6.pos()                       lista
--   dc6.pos('arma', x, y)           texto alineado a la izquierda: x = borde izquierdo
--   dc6.pos('balas', 300, 16, 'der')  alineado a la DERECHA: x = borde derecho
--   dc6.pos('vida', x, y)           la palabra VIDA ('izq' vuelve a alinear a la izquierda)
--   dc6.pos('barra', x, y)          esquina sup. izq. del relleno (50x6, marco de 1 px)
local POSN={arma=0,balas=1,vida=2,barra=3}
local function rds16(a) local v=rd16(a) if v>=0x8000 then v=v-0x10000 end return v end
function dc6.pos(k,x,y,al)
  if k then
    local i=POSN[k] if not i then print('[dc6] elementos: arma balas vida barra') return end
    if x then wr16(0x800DA0B0+i*4, bit.band(x,0xFFFF)) end
    if y then wr16(0x800DA0B0+i*4+2, bit.band(y,0xFFFF)) end
    if i<3 then
      local r=rd8(0x800DA0F6)
      if al=='der' then r=bit.bor(r,bit.lshift(1,i)) elseif al=='izq' then r=bit.band(r,bit.bnot(bit.lshift(1,i))) end
      wr8(0x800DA0F6, r)
    end
  end
  local out={}
  for _,n in ipairs({'arma','balas','vida','barra'}) do
    local i=POSN[n]
    local der=i<3 and bit.band(rd8(0x800DA0F6),bit.lshift(1,i))~=0
    out[#out+1]=string.format('%s=%d,%d%s',n,rds16(0x800DA0B0+i*4),rds16(0x800DA0B0+i*4+2),der and ' der' or '')
  end
  print('[dc6] HUD: '..table.concat(out,'  ')..(bit.band(rd8(OPTA),8)==0 and '' or '  (oculto)'))
end
-- OPCIONES (v6.13): un byte del bloque de configuracion del juego (0x800BA6AD),
-- el mismo que cambia el menu OPCIONES > CONTROL Y CAMARA y que se guarda con la partida.
--   dc6.opt()                      lista
--   dc6.opt('control','tanque')    'moderno' | 'tanque'
--   dc6.opt('camara','espalda')    'original' | 'hombro' | 'espalda'
--   dc6.opt('hud','no')            'si' | 'no'
--   dc6.opt('correr','no')         'si' | 'no'
local OPTA=0x800BA6AD
local OPTS={control={0,1,{'moderno','tanque'}},camara={1,3,{'original','hombro','espalda'}},hud={3,1,{'si','no'}},correr={4,1,{'si','no'}}}
function dc6.opt(k,v)
  if k then
    local o=OPTS[k] if not o then print('[dc6] opciones: control camara hud correr') return end
    local n=nil for i,name in ipairs(o[3]) do if name==v then n=i-1 end end
    if n==nil then print('[dc6] valores: '..table.concat(o[3],' ')) return end
    local cur=rd8(OPTA)
    wr8(OPTA, bit.bor(bit.band(cur, bit.bnot(bit.lshift(o[2],o[1]))), bit.lshift(n,o[1])))
  end
  local cur=rd8(OPTA) local out={}
  for _,name in ipairs({'control','camara','hud','correr'}) do
    local o=OPTS[name] local val=bit.band(bit.rshift(cur,o[1]),o[2])
    out[#out+1]=name..'='..(o[3][val+1] or '?')
  end
  print(string.format('[dc6] opciones (%02X): %s',cur,table.concat(out,'  ')))
end
function dc6.hud(on) if on ~= nil then dc6.opt('hud', on and 'si' or 'no') else dc6.opt() end end
-- CAMARA AL HOMBRO en vivo (unidades del juego; 4096 = una vuelta en la inclinacion).
--   dc6.cam()                    lista
--   dc6.cam('alto', 1300)        punto mirado sobre los pies (mas = mira mas arriba)
--   dc6.cam('dist', 2200)        distancia (menos = mas cerca)
--   dc6.cam('lado', -350)        corrimiento lateral (negativo = Regina a la izquierda)
--   dc6.cam('incl', 120)         inclinacion al recentrar con L3 / R3
--   dc6.cam('a_alto', v) dc6.cam('a_dist', v) dc6.cam('a_lado', v)   lo mismo APUNTANDO (L2)
--   Camara de ESPALDA: los mismos con e_ adelante (e_alto e_dist e_lado e_incl) y
--   ea_ para apuntando (ea_alto ea_dist ea_lado).
-- Alto, distancia y lado se ven al instante; la inclinacion, al apretar L3.
local CAMN={alto=0,dist=1,lado=2,incl=3,a_alto=4,a_dist=5,a_lado=6,
            e_alto=7,e_dist=8,e_lado=9,e_incl=10,ea_alto=11,ea_dist=12,ea_lado=13}
local CAMO={'alto','dist','lado','incl','a_alto','a_dist','a_lado','e_alto','e_dist','e_lado','e_incl','ea_alto','ea_dist','ea_lado'}
function dc6.cam(k,v)
  if k then
    local i=CAMN[k] if not i then print('[dc6] parametros: '..table.concat(CAMO,' ')) return end
    if v then wr16(0x800DA0C4+i*2, bit.band(v,0xFFFF)) end
  end
  local out={}
  for _,n in ipairs(CAMO) do out[#out+1]=string.format('%s=%d',n,rds16(0x800DA0C4+CAMN[n]*2)) end
  print('[dc6] camara: '..table.concat(out,'  ',1,7))
  print('[dc6] espalda: '..table.concat(out,'  ',8,14))
end
-- CORRER automatico: ahora es una opcion del menu. dc6.run() / dc6.run(true/false)
function dc6.run(on) if on ~= nil then dc6.opt('correr', on and 'si' or 'no') else dc6.opt() end end
-- DIAGNOSTICO del HUD: registra por Vsync cuando el HUD NO se dibujo y por que.
--   dc6.hudWhy()  -> jugar / cruzar el cambio de camara   dc6.hudWhy() otra vez = cortar
local WHY={[0]='dibujo',[1]='OT invalida',[2]='misma OT que el frame anterior',[3]='cinematica (bandera de bloqueo)',[4]='oculto (opcion HUD = no)'}
local whyL=nil
function dc6.hudWhy()
  if whyL then whyL:remove() whyL=nil print('[dc6] hudWhy cortado') return end
  local lastCnt, still, v, lastMsg = rd16(0x800DA0F4), 0, 0, ''
  local lastCam, camStill = rd16(0x800DA0F2), 0
  whyL=PCSX.Events.createEventListener('GPU::Vsync', function()
    v=v+1
    local c=rd16(0x800DA0F4)
    local msg
    if c==lastCnt then
      still=still+1
      msg = still>=3 and 'el jugador NO se actualiza (no corre el enganche)' or nil
    else
      still=0; lastCnt=c
      local w=rd8(0x800DA0F0)
      msg = w~=0 and ('no dibujo: '..(WHY[w] or w)) or 'dibujo'
    end
    local cc=rd16(0x800DA0F2)
    if cc==lastCam then camStill=camStill+1 else camStill=0; lastCam=cc end
    if msg then msg=msg..(camStill>=3 and ' | camara: NO corre' or ' | camara: corre') end
    if msg and msg~=lastMsg then
      print(string.format('[hud] v%-5d %-72s estado %02X/%02X  3C=%02X 3D=%02X  OT=%08X',v,msg,
        rd8(0x800BAF32),rd8(0x800BAF3E),rd8(0x800B1E50),rd8(0x800B1E51),rd(0x800AE280)))
      lastMsg=msg
    end
  end)
  print('[dc6] hudWhy: solo imprime cuando cambia. Cruza un cambio de camara y despues dc6.hudWhy() para cortar.')
end
print('[dc6] listo: dc6.install()  dc6.remove()  dc6.verify()  dc6.cut(n)  dc6.pump(n)  dc6.cuts()  dc6.pos(k,x,y[,"der"])  dc6.hud(true/false)  dc6.cam(k,v)  dc6.run()  dc6.opt(k,v)  dc6.hudWhy()')
